IMAGE_EXTENSIONS = {"jpg", "jpeg", "png", "gif", "webp", "avif", "bmp", "svg"}
VIDEO_EXTENSIONS = {"mp4", "webm", "ogv", "mov", "m4v"}


class UpgradeError(RuntimeError):
    pass


def configure_console() -> None:
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, OSError):
            pass


def pause(message: str = "\n按任意键退出") -> None:
    print(message, end="", flush=True)
    if os.name == "nt":
        try:
            import msvcrt
            msvcrt.getwch()
            print()
            return
        except (ImportError, OSError):
            pass
    try:
        input()
    except EOFError:
        pass


def read_source(path: Path) -> tuple[str, bool, str]:
    raw = path.read_bytes()
    has_bom = raw.startswith(b"\xef\xbb\xbf")
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise UpgradeError("报告不是可识别的 UTF-8 HTML") from exc
    newline = "\r\n" if raw.count(b"\r\n") > raw.count(b"\n") // 2 else "\n"
    return text, has_bom, newline


def unique_path(directory: Path, stem: str, suffix: str = "") -> Path:
    candidate = directory / f"{stem}{suffix}"
    counter = 2
    while candidate.exists():
        candidate = directory / f"{stem}({counter}){suffix}"
        counter += 1
    return candidate


def extract_report_data(source: str) -> tuple[str, dict]:
    match = JSON_RE.search(source)
    if not match:
        raise UpgradeError("未找到 dcc-download-stats-data 统计数据")
    raw_json = match.group(2)
    try:
        data = json.loads(raw_json)
    except json.JSONDecodeError as exc:
        raise UpgradeError("统计数据 JSON 无法解析") from exc
    return raw_json, data


def all_items_by_id(data: dict) -> dict[str, dict]:
    result: dict[str, dict] = {}
    runs = data.get("runs") if isinstance(data, dict) else None
    for run in runs if isinstance(runs, list) else []:
        items = run.get("items") if isinstance(run, dict) else None
        for item in items if isinstance(items, list) else []:
            if not isinstance(item, dict):
                continue
            item_id = str(item.get("aweme_id") or "")
            if item_id:
                result[item_id] = item
    return result


def extract_rows(source: str) -> list[re.Match[str]]:
    rows = list(ROW_RE.finditer(source))
    if not rows:
        raise UpgradeError("未找到统计报告的作品行")
    return rows


def row_id(row_html: str) -> str:
    match = ID_RE.search(html.unescape(row_html))
    return match.group(1) if match else ""


def validate_row_mapping(rows: list[re.Match[str]], items: dict[str, dict]) -> list[str]:
    ids = [row_id(row.group(0)) for row in rows]
    seen: set[str] = set()
    duplicates: list[str] = []
    for value in ids:
        if value and value in seen:
            duplicates.append(value)
        seen.add(value)
    missing_ids = [str(index + 1) for index, value in enumerate(ids) if not value]
    unknown = [value for value in ids if value and value not in items]
    if missing_ids or unknown or duplicates or len(ids) != len(items):
        details = [f"rows={len(ids)}", f"unique_items={len(items)}"]
        if missing_ids:
            details.append("无ID行=" + ",".join(missing_ids[:10]))
        if unknown:
            details.append("无数据ID=" + ",".join(unknown[:10]))
        if duplicates:
            details.append("重复ID=" + ",".join(sorted(set(duplicates))[:10]))
        raise UpgradeError("多批次数据与页面作品行无法一一对应；" + "，".join(details))
    return ids


def media_kind(filename: str) -> str:
    extension = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    if extension in IMAGE_EXTENSIONS:
        return "image"
    if extension in VIDEO_EXTENSIONS:
        return "video"
    return "other"


def first_local_media(item: dict) -> tuple[str, str] | None:
    filenames = item.get("filenames") if isinstance(item, dict) else None
    for entry in filenames if isinstance(filenames, list) else []:
        if isinstance(entry, str):
            name, missing = entry, False
        elif isinstance(entry, dict):
            name, missing = str(entry.get("name") or ""), bool(entry.get("missing"))
        else:
            continue
        kind = media_kind(name)
        if name and not missing and kind in {"image", "video"}:
            return name, kind
    return None


def relative_url(filename: str) -> str:
    return "./" + urllib.parse.quote(filename.replace("\\", "/"), safe="/-._~")


def replace_rows(source: str, transform) -> str:
    parts: list[str] = []
    position = 0
    for index, match in enumerate(extract_rows(source)):
        parts.append(source[position:match.start()])
        parts.append(transform(match.group(0), index))
        position = match.end()
    parts.append(source[position:])
    return "".join(parts)


def local_media_covers(
    source: str,
    ids: list[str],
    items: dict[str, dict],
    target_indices: set[int] | None = None,
) -> tuple[str, dict[str, int]]:
    counts = {"image": 0, "video": 0, "empty": 0, "missing_on_disk": 0}

    def transform(row: str, index: int) -> str:
        if target_indices is not None and index not in target_indices:
            return row
        chosen = first_local_media(items[ids[index]])
        if not chosen:
            counts["empty"] += 1
            replacement = '<div class="cover-placeholder">无本地媒体</div>'
        else:
            filename, kind = chosen
            counts[kind] += 1
            if not (REPORT_DIR / filename).is_file():
                counts["missing_on_disk"] += 1
            url = html.escape(relative_url(filename), quote=True)
            alt = html.escape(
                str(items[ids[index]].get("title") or items[ids[index]].get("author") or "本地封面"),
                quote=True,
            )
            if kind == "image":
                replacement = (
                    f'<img src="{url}" alt="{alt}" '
                    'class="cover-img cover-local-media" loading="lazy">'
                )
            else:
                replacement = (
                    f'<video src="{url}" aria-label="{alt}" '
                    'class="cover-img cover-local-media cover-local-video" '
                    'data-cover-frame="20" preload="none" muted playsinline></video>'
                )
        if not COVER_RE.search(row):
            raise UpgradeError(f"第 {index + 1} 个作品行没有可替换的封面元素")
        return COVER_RE.sub(replacement, row, count=1)

    return replace_rows(source, transform), counts


def cover_url_from_row(row: str) -> str:
    cover = COVER_RE.search(row)
    if not cover:
        return ""
    src = SRC_RE.search(cover.group(0))
    return html.unescape(src.group(2)).strip() if src else ""


def extension_from_response(url: str, content_type: str) -> str:
    media_type = (content_type or "").split(";", 1)[0].strip().lower()
    known = {
        "image/jpeg": ".jpg",
        "image/png": ".png",
        "image/webp": ".webp",
        "image/gif": ".gif",
        "image/avif": ".avif",
        "image/bmp": ".bmp",
    }
    if media_type in known:
        return known[media_type]
    guessed = mimetypes.guess_extension(media_type) if media_type.startswith("image/") else None
    if guessed:
        return ".jpg" if guessed in {".jpe", ".jpeg"} else guessed
    path_suffix = Path(urllib.parse.urlsplit(url).path).suffix.lower()
    allowed = {".jpg", ".jpeg", ".png", ".webp", ".gif", ".avif", ".bmp"}
    return path_suffix if path_suffix in allowed else ".jpg"


def downloaded_cover_stem(item: dict, item_id: str) -> str:
    filenames = item.get("filenames") if isinstance(item, dict) else None
    for entry in filenames if isinstance(filenames, list) else []:
        if isinstance(entry, str):
            name = entry
        elif isinstance(entry, dict):
            name = str(entry.get("name") or "")
        else:
            continue
        basename = name.replace("\\", "/").rsplit("/", 1)[-1]
        stem = Path(basename).stem.rstrip(" .")
        if not stem:
            continue
        group_name = re.sub(r"_\d+$", "", stem).rstrip(" .") or stem
        return group_name + "_封面"
    return str(item_id).rstrip(" .") + "_封面"


def download_cover(index: int, cover_stem: str, url: str, directory: Path) -> tuple[int, str, str]:
    if urllib.parse.urlsplit(url).scheme not in {"http", "https"}:
        return index, "", "不是 HTTP/HTTPS 地址"
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/140 Safari/537.36",
        "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
        "Referer": "https://www.douyin.com/",
    }
    last_error: Exception | None = None
    for attempt in range(3):
        try:
            request = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(request, timeout=25) as response:
                payload = response.read(20 * 1024 * 1024 + 1)
                content_type = response.headers.get("Content-Type", "")
            if len(payload) > 20 * 1024 * 1024:
                raise UpgradeError("单张封面超过 20 MB 安全上限")
            if not payload or payload.lstrip().startswith((b"<html", b"<!DOCTYPE", b"{")):
                raise UpgradeError("返回内容不是图片")
            extension = extension_from_response(url, content_type)
            filename = cover_stem + extension
            destination = directory / filename
            temporary = directory / (filename + ".part")
            temporary.write_bytes(payload)
            os.replace(temporary, destination)
            return index, filename, ""
        except Exception as exc:
            last_error = exc
            if attempt < 2:
                time.sleep(0.6 * (attempt + 1))
    return index, "", str(last_error or "未知错误")


def downloaded_covers(
    source: str,
    ids: list[str],
    items: dict[str, dict],
    cover_directory: Path,
    validate_only: bool,
) -> tuple[str, dict[str, object]]:
    rows = extract_rows(source)
    jobs: list[tuple[int, str, str]] = []
    expected_filenames: dict[int, str] = {}
    used_stems: dict[str, int] = {}
    for index, row in enumerate(rows):
        url = cover_url_from_row(row.group(0))
        if url:
            item_id = ids[index]
            base_stem = downloaded_cover_stem(items[item_id], item_id)
            occurrence = used_stems.get(base_stem, 0) + 1
            used_stems[base_stem] = occurrence
            cover_stem = base_stem if occurrence == 1 else f"{base_stem}({occurrence})"
            jobs.append((index, cover_stem, url))
            expected_filenames[index] = cover_stem + extension_from_response(url, "")
    if not jobs:
        raise UpgradeError("报告中未找到可下载的封面链接")
    if validate_only:
        return source, {"found": len(jobs), "downloaded": 0, "failed": 0, "failed_indices": []}

    cover_directory.mkdir(parents=False, exist_ok=False)
    downloaded: dict[int, str] = {}
    failures: dict[int, str] = {}
    print(f"\n开始下载 {len(jobs)} 张封面，请稍候…")
    with concurrent.futures.ThreadPoolExecutor(max_workers=6) as executor:
        futures = [executor.submit(download_cover, *job, cover_directory) for job in jobs]
        completed = 0
        for future in concurrent.futures.as_completed(futures):
            index, filename, error = future.result()
            completed += 1
            if filename:
                downloaded[index] = filename
            else:
                failures[index] = error
            print(f"\r已处理：{completed}/{len(jobs)}", end="", flush=True)
    print()
    result, _ = point_covers_to_local_folder(source, downloaded, cover_directory)
    if failures:
        failure_log = cover_directory / "下载失败记录.txt"
        lines = [
            f"第 {index + 1} 个封面：{message}；本地封面文件名：{expected_filenames[index]}"
            for index, message in sorted(failures.items())
        ]
        failure_log.write_text("\n".join(lines), encoding="utf-8")
    return result, {
        "found": len(jobs),
        "downloaded": len(downloaded),
        "failed": len(failures),
        "failed_indices": sorted(failures),
        "failed_local_filenames": {
            index: expected_filenames[index] for index in sorted(failures)
        },
    }


def point_covers_to_local_folder(
    source: str,
    filenames: dict[int, str],
    cover_directory: Path,
) -> tuple[str, int]:
    folder_url = urllib.parse.quote(cover_directory.name, safe="-._~")
    changed = 0

    def transform(row: str, index: int) -> str:
        nonlocal changed
        filename = filenames.get(index)
        if not filename:
            return row
        cover = COVER_RE.search(row)
        if not cover:
            return row
        local_url = f"./{folder_url}/{urllib.parse.quote(filename, safe='-._~')}"
        replacement = SRC_RE.sub(f'src="{html.escape(local_url, quote=True)}"', cover.group(0), count=1)
        changed += 1
        return row[:cover.start()] + replacement + row[cover.end():]

    return replace_rows(source, transform), changed


def inject_player_css(source: str) -> str:
    cleaned = PLAYER_CSS_RE.sub("", source)
    close = re.search(r"</style>", cleaned, re.IGNORECASE)
    if not close:
        raise UpgradeError("报告缺少 </style>，无法注入播放器样式")
    return cleaned[:close.start()] + "\n\n" + PLAYER_CSS + "\n" + cleaned[close.start():]


def inject_local_cover_css(source: str) -> str:
    cleaned = re.sub(
        r'\s*/\* DCC_LOCAL_COVER_STYLE_V1 \*/.*?/\* END DCC_LOCAL_COVER_STYLE_V1 \*/',
        "",
        source,
        flags=re.IGNORECASE | re.DOTALL,
    )
    close = re.search(r"</style>", cleaned, re.IGNORECASE)
    if not close:
        raise UpgradeError("报告缺少 </style>，无法注入本地封面样式")
    return cleaned[:close.start()] + "\n\n" + LOCAL_COVER_CSS + "\n" + cleaned[close.start():]


def replace_modal(source: str) -> str:
    pattern = re.compile(
        r'<div\b(?=[^>]*\bid\s*=\s*["\']mediaModal["\'])[^>]*>\s*'
        r'<button\b[^>]*>.*?</button>\s*'
        r'<div\b(?=[^>]*\bid\s*=\s*["\']mediaContainer["\'])[^>]*>.*?</div>\s*'
        r"</div>",
        re.IGNORECASE | re.DOTALL,
    )
    replacement = """<div aria-hidden="true" class="modal" id="mediaModal">
<button aria-label="关闭图文查看器" class="close-btn" onclick="closeModal()" type="button">×</button>
<div class="modal-content" id="mediaContainer"></div>
</div>"""
    result, count = pattern.subn(replacement, source, count=1)
    if count != 1:
        raise UpgradeError("无法唯一定位原报告的媒体弹窗")
    return result


def replace_player_script(source: str) -> str:
    matches = list(SCRIPT_RE.finditer(source))
    target = next(
        (
            match
            for match in matches
            if "application/json" not in match.group("attrs").lower()
            and (
                "function openModal" in match.group("code")
                or "function renderViewer" in match.group("code")
                or "DCC_MEDIA_PLAYER_V22_OPTIMIZED" in match.group("code")
            )
        ),
        None,
    )
    if target is None:
        raise UpgradeError("无法定位原报告的可执行 JavaScript")
    replacement = "<script>\n" + PLAYER_JS + "\n</script>"
    return source[:target.start()] + replacement + source[target.end():]


def inject_cover_video_script(source: str) -> str:
    source = re.sub(
        r'\s*<script[^>]*>\s*/\* DCC_LOCAL_COVER_FRAME_\d+_V1 \*/.*?</script>',
        "",
        source,
        flags=re.IGNORECASE | re.DOTALL,
    )
    close = re.search(r"</body>", source, re.IGNORECASE)
    if not close:
        raise UpgradeError("报告缺少 </body>")
    block = "\n<script>\n" + COVER_VIDEO_JS + "\n</script>\n"
    return source[:close.start()] + block + source[close.start():]


def normalize_without_covers(source: str) -> str:
    return COVER_PLACEHOLDER_RE.sub("<COVER>", COVER_RE.sub("<COVER>", source))


def validate_output(original: str, output: str, expected_rows: int, expect_player: bool) -> None:
    original_json, _ = extract_report_data(original)
    output_json, _ = extract_report_data(output)
    if hashlib.sha256(original_json.encode("utf-8")).digest() != hashlib.sha256(output_json.encode("utf-8")).digest():
        raise UpgradeError("安全校验失败：内嵌统计 JSON 被意外修改")
    if len(extract_rows(output)) != expected_rows:
        raise UpgradeError("安全校验失败：生成前后作品行数不一致")
    player_markers = (
        "DCC_MEDIA_PLAYER_PATCH_V2",
        "DCC_MEDIA_PLAYER_V22_OPTIMIZED",
        "DCC_MULTI_BATCH_ORDER_V1",
    )
    if expect_player:
        if output.count("DCC_MEDIA_PLAYER_PATCH_V2") != 2:
            raise UpgradeError("安全校验失败：播放器 CSS 标记数量异常")
        if output.count("DCC_MEDIA_PLAYER_V22_OPTIMIZED") != 1:
            raise UpgradeError("安全校验失败：播放器 JavaScript 注入数量异常")
        if output.count("DCC_MULTI_BATCH_ORDER_V1") != 1:
            raise UpgradeError("安全校验失败：多批次排序保护未正确注入")
        if len(re.findall(r'\bid\s*=\s*["\']mediaModal["\']', output, re.IGNORECASE)) != 1:
            raise UpgradeError("安全校验失败：媒体弹窗数量异常")
    elif any(output.count(marker) != original.count(marker) for marker in player_markers):
        raise UpgradeError("安全校验失败：未选择播放器，但播放器内容发生变化")

    original_rows = [normalize_without_covers(match.group(0)) for match in extract_rows(original)]
    output_rows = [normalize_without_covers(match.group(0)) for match in extract_rows(output)]
    if original_rows != output_rows:
        raise UpgradeError("安全校验失败：封面以外的表格内容发生变化")


def write_atomic(path: Path, text: str, bom: bool) -> None:
    payload = text.encode("utf-8")
    if bom:
        payload = b"\xef\xbb\xbf" + payload
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_bytes(payload)
    os.replace(temporary, path)


def choose_mode() -> str:
    print("已检测到统计报告，是否要作出以下修改：")
    print("1、直接注入媒体播放器")
    print("2、将统计报告的封面转为本地文件")
    print("3、将统计报告的封面转为本地文件，并注入媒体播放器")
    print("4、扫描html文件，将封面下载至本地")
    print("5、扫描html文件，将封面下载至本地，并注入媒体播放器")
    while True:
        try:
            value = input("\n请输入 1、2、3、4 或 5：").strip()
        except EOFError:
            return ""
        if value in {"1", "2", "3", "4", "5"}:
            return value
        print("输入无效，请重新输入。")


def choose_failed_cover_fallback(failed_count: int) -> str:
    print(f"\n有{failed_count}张封面下载失败，是否将下载失败的组别封面转为本地媒体？")
    print("1、是")
    print("2、否")
    while True:
        try:
            value = input("\n请输入 1 或 2：").strip()
        except EOFError:
            return "2"
        if value in {"1", "2"}:
            return value
        print("输入无效，请重新输入。")


def choose_failed_cover_location() -> str:
    print("\n请选择下载失败组别的封面处理方式：")
    print("1、将失败的组别保留原网络封面")
    print("2、将失败的组别封面定位为本地封面文件夹中的封面")
    while True:
        try:
            value = input("\n请输入 1 或 2：").strip()
        except EOFError:
            return "1"
        if value in {"1", "2"}:
            return value
        print("输入无效，请重新输入。")


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(add_help=True)
    parser.add_argument("--choice", choices=("1", "2", "3", "4", "5"), help=argparse.SUPPRESS)
    parser.add_argument("--fallback-choice", choices=("1", "2"), help=argparse.SUPPRESS)
    parser.add_argument("--failed-cover-choice", choices=("1", "2"), help=argparse.SUPPRESS)
    parser.add_argument("--report-dir", type=Path, help=argparse.SUPPRESS)
    parser.add_argument("--no-pause", action="store_true", help=argparse.SUPPRESS)
    parser.add_argument("--validate-only", action="store_true", help=argparse.SUPPRESS)
    return parser.parse_args()


def main() -> int:
    configure_console()
    args = parse_arguments()
    global REPORT_DIR
    REPORT_DIR = (args.report_dir or Path(sys.argv[0]).resolve().parent).resolve()
    report_path = REPORT_DIR / REPORT_FILENAME
    if not report_path.is_file():
        print("未检测到相关文件，请按任意键退出")
        if not args.no_pause:
            pause("")
        return 1

    choice = args.choice or choose_mode()
    if choice not in {"1", "2", "3", "4", "5"}:
        print("未选择处理方式。")
        if not args.no_pause:
            pause()
        return 1

    player_requested = choice in {"1", "3", "5"}
    cover_mode = "local" if choice in {"2", "3"} else "download" if choice in {"4", "5"} else "none"
    output_stems = {
        "1": "抖铲铲下载统计报告_播放器",
        "2": "抖铲铲下载统计报告_本地媒体封面",
        "3": "抖铲铲下载统计报告_播放器_本地媒体封面",
        "4": "抖铲铲下载统计报告_下载封面",
        "5": "抖铲铲下载统计报告_播放器_下载封面",
    }
    cover_directory: Path | None = None
    cover_stats: dict[str, object] | None = None
    fallback_stats: dict[str, int] | None = None
    fallback_choice = ""
    failed_cover_choice = ""
    failed_cover_localized = 0
    try:
        source, has_bom, newline = read_source(report_path)
        _, data = extract_report_data(source)
        rows = extract_rows(source)
        items = all_items_by_id(data)
        ids = validate_row_mapping(rows, items)
        print(f"\n已识别：{len(data.get('runs') or [])} 个批次，{len(rows)} 个作品组。")

        output_stem = output_stems[choice]
        transformed = source
        has_local_media_covers = False
        if cover_mode == "local":
            transformed, cover_stats = local_media_covers(source, ids, items)
            has_local_media_covers = True
        elif cover_mode == "download":
            cover_directory = unique_path(REPORT_DIR, "抖铲铲统计报告_本地封面")
            transformed, cover_stats = downloaded_covers(
                source,
                ids,
                items,
                cover_directory,
                args.validate_only,
            )
            if args.validate_only:
                print(f"下载模式结构校验通过：找到 {cover_stats['found']} 个网络封面。")
                return 0
            failed_count = int(cover_stats["failed"])
            if failed_count:
                fallback_choice = args.fallback_choice or choose_failed_cover_fallback(failed_count)
                if fallback_choice == "1":
                    failed_indices = {int(index) for index in cover_stats["failed_indices"]}
                    transformed, fallback_stats = local_media_covers(
                        transformed,
                        ids,
                        items,
                        target_indices=failed_indices,
                    )
                    has_local_media_covers = True
                else:
                    failed_cover_choice = args.failed_cover_choice or choose_failed_cover_location()
                    if failed_cover_choice == "2":
                        failed_local_filenames = {
                            int(index): str(filename)
                            for index, filename in dict(cover_stats["failed_local_filenames"]).items()
                        }
                        transformed, failed_cover_localized = point_covers_to_local_folder(
                            transformed,
                            failed_local_filenames,
                            cover_directory,
                        )

        if has_local_media_covers:
            transformed = inject_cover_video_script(transformed)
            if not player_requested:
                transformed = inject_local_cover_css(transformed)

        if player_requested:
            transformed = inject_player_css(transformed)
            transformed = replace_modal(transformed)
            transformed = replace_player_script(transformed)
        validate_output(source, transformed, len(rows), expect_player=player_requested)

        if newline == "\r\n":
            transformed = transformed.replace("\r\n", "\n").replace("\n", "\r\n")

        output_path = unique_path(REPORT_DIR, output_stem, ".html")
        write_atomic(output_path, transformed, has_bom)

        print("\n处理完成。")
        print(f"新 HTML：{output_path.name}")
        print(f"原报告保持不变：{report_path.name}")
        if cover_mode == "none":
            print("媒体播放器：已注入。")
        elif cover_mode == "local" and cover_stats is not None:
            print(
                f"本地封面：图片 {cover_stats['image']} 组，"
                f"视频第20帧 {cover_stats['video']} 组，无可用媒体 {cover_stats['empty']} 组。"
            )
            if cover_stats["missing_on_disk"]:
                print(
                    f"提示：当前有 {cover_stats['missing_on_disk']} 组首媒体未在目录中找到；"
                    "HTML 已保留对报告记录文件名的引用。"
                )
        elif cover_mode == "download" and cover_stats is not None:
            print(f"封面目录：{cover_directory.name if cover_directory else ''}")
            print(
                f"网络封面：发现 {cover_stats['found']} 张，"
                f"成功 {cover_stats['downloaded']} 张，失败 {cover_stats['failed']} 张。"
            )
            if int(cover_stats["failed"]):
                if fallback_choice == "1" and fallback_stats is not None:
                    print(
                        f"失败封面已改用本地媒体：图片 {fallback_stats['image']} 组，"
                        f"视频第20帧 {fallback_stats['video']} 组，"
                        f"无可用媒体 {fallback_stats['empty']} 组。"
                    )
                    if fallback_stats["missing_on_disk"]:
                        print(
                            f"提示：其中有 {fallback_stats['missing_on_disk']} 组首媒体未在目录中找到；"
                            "HTML 已保留对报告记录文件名的引用。"
                        )
                elif failed_cover_choice == "2":
                    print(
                        f"下载失败的组别已定位到本地封面文件夹："
                        f"{failed_cover_localized} 组。"
                    )
                else:
                    print("下载失败的组别保留原网络封面。")

        if not args.no_pause:
            pause()
        return 0
    except Exception as exc:
        print(f"\n处理失败：{exc}")
        if cover_directory and cover_directory.exists() and not any(cover_directory.iterdir()):
            try:
                cover_directory.rmdir()
            except OSError:
                pass
        if not args.no_pause:
            pause()
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
